using NUnit.Framework;using System.Linq;using CashflowChains.Domain;
public class CityInsightTests {
 [Test] public void FirstThreeCitiesTeachOneConnectionThenRotationThenCombineThem(){var first=new CityRun(0);Assert.AreEqual(0,first.Preview().Credits);Assert.True(first.Move(2,2,2));Assert.AreEqual(first.Mission.Par,first.Preview().Credits);var second=new CityRun(1);Assert.AreEqual(0,second.Preview().Credits);Assert.True(second.Rotate(3));Assert.AreEqual(second.Mission.Par,second.Preview().Credits);var third=new CityRun(2);Assert.AreEqual(0,third.Preview().Credits);Assert.True(third.Move(1,1,2));Assert.AreEqual(0,third.Preview().Credits);Assert.True(third.Rotate(3));Assert.AreEqual(third.Mission.Par,third.Preview().Credits);}
 [Test] public void FeedbackExplainsActualImprovementAndDoesNotMutateBoards(){var run=new CityRun(0);var before=run.Board.Copy();string fingerprint=before.Fingerprint();run.Move(2,2,2);var after=run.Board.Fingerprint();var insight=CityInsight.Compare(before,run.Board,run.Mission.Multiplier,2);Assert.AreEqual("CUSTOMERS CONNECTED",insight.Title);Assert.AreEqual(run.Preview().Credits,insight.Delta);Assert.AreEqual(fingerprint,before.Fingerprint());Assert.AreEqual(after,run.Board.Fingerprint());}
 [Test] public void CustomerConnectionDoesNotClaimProfitWhenSuppliesAreMissing(){var run=new CityRun(1);var text=CityInsight.Describe(run.Board,run.Preview(),2);StringAssert.Contains("supplies",text);Assert.AreEqual(0,run.Preview().Credits);var before=run.Board.Copy();run.Rotate(3);var insight=CityInsight.Compare(before,run.Board,run.Mission.Multiplier,3);Assert.AreEqual("SUPPLIES CONNECTED",insight.Title);Assert.Greater(insight.Delta,0);}
 [Test] public void BreakingConnectionExplainsLossAndUndoRestoresActualCash(){var run=new CityRun(0);run.Move(2,2,2);var before=run.Board.Copy();long value=run.Preview().Credits;run.Move(2,3,2);var insight=CityInsight.Compare(before,run.Board,run.Mission.Multiplier,2);Assert.AreEqual(-value,insight.Delta);Assert.True(run.Undo());Assert.AreEqual(value,run.Preview().Credits);}
 [Test] public void DifferentLegalLayoutsCanEarnTheSameScore(){for(int level=0;level<3;level++){var m=Campaign.Get(level);var b=m.Solution.Copy();foreach(var n in b.Nodes){n.Y--;};b.Validate();var run=new CityRun(level,b);Assert.AreEqual(m.Par,run.Preview().Credits);Assert.AreEqual(3,run.Stars(run.Preview().Credits));Assert.AreNotEqual(m.Solution.Fingerprint(),b.Fingerprint());}}
}
